const store = globalThis as unknown as {
  notificationPreferences?: Map<string, boolean>
}

const preferences = (store.notificationPreferences ??= new Map<string, boolean>())

export function getNotificationPreference(userId: string): boolean {
  return preferences.get(userId) ?? false
}

export function setNotificationPreference(userId: string, enabled: boolean): void {
  preferences.set(userId, enabled)
}

