'use server'

import { refresh } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from '@/app/lib/preferences'

export async function toggleNotificationPreference(userId: string) {
  const current = getNotificationPreference(userId)
  setNotificationPreference(userId, !current)

  refresh()

  return !current
}

