args.content:
import { toggleNotificationPreference } from '@/app/actions'
import { getNotificationPreference } from '@/app/lib/preferences'

const USER_ID = 'demo-user'

export default function Home() {
  const enabled = getNotificationPreference(USER_ID)

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotificationPreference.bind(null, USER_ID)}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

